import java.io.*;
import java.util.*;

// Stand-in for the given Main.class (javap -c). TC2 prints getOwner() + "," + getPrice() itself — NO space
class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter owner: ");
        String owner = sc.nextLine();
        System.out.print("Enter price: ");
        int price = sc.nextInt();
        System.out.print("Enter color: ");
        int color = sc.nextInt();
        System.out.println("1.Test toString()");
        System.out.println("2.Test setData()");
        System.out.println("3.Test getValue()");
        System.out.print("Enter TC(1,2,3): ");
        int tc = sc.nextInt();
        Cala cala = new Cala(owner, price);
        SpecCala spec = new SpecCala(color, owner, price);
        switch (tc) {
            case 1:
                System.out.println("OUTPUT:");
                System.out.println(cala.toString());
                System.out.println(spec.toString());
                break;
            case 2:
                System.out.println("OUTPUT:");
                spec.setData();
                System.out.println(spec.getOwner() + "," + spec.getPrice());
                break;
            case 3:
                System.out.println("OUTPUT:");
                System.out.println(spec.getValue());
                break;
        }
    }
}
